-- Additional completion controls. Synthetic transaction only; no customer mail.
begin;
create temp table completion_threshold_ids(id uuid,expected text);
grant select,insert on completion_threshold_ids to authenticated;
create temp table completion_portal_ids(request_id uuid,share_id uuid,customer_id uuid);
grant select,insert on completion_portal_ids to authenticated,anon;
create temp table work_test_ids(owner_id uuid,editor_id uuid,session_id uuid,editor_session uuid,factor_id uuid,editor_factor uuid);
insert into work_test_ids values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on work_test_ids to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at) select owner_id,'owner-fixture@example.invalid',now() from work_test_ids union all select editor_id,'editor-fixture@example.invalid',now() from work_test_ids;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) select factor_id,owner_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'FIXTURE',now(),now() from work_test_ids union all select editor_factor,editor_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'FIXTURE',now(),now() from work_test_ids;
insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) select session_id,owner_id,factor_id,'aal2'::auth.aal_level,now(),now() from work_test_ids union all select editor_session,editor_id,editor_factor,'aal2'::auth.aal_level,now(),now() from work_test_ids;
insert into public.work_members(email,user_id,role) select 'owner-fixture@example.invalid',owner_id,'owner' from work_test_ids union all select 'editor-fixture@example.invalid',editor_id,'editor' from work_test_ids;
insert into private.work_job_config(id,proof_hash) values(1,encode(sha256(convert_to(repeat('b',64),'UTF8')),'hex')) on conflict(id) do update set proof_hash=excluded.proof_hash;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$declare c jsonb;d jsonb;cmd jsonb;cid uuid;sid uuid;item uuid;po uuid;pol uuid;ord uuid;ol uuid;stock uuid;hold uuid;pay uuid;expense uuid;bank uuid;e uuid;ef uuid;ei uuid;ep uuid;es uuid;visit uuid;contract uuid;message uuid;denied boolean;key uuid;begin
 foreach e in array array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()] loop
  if ef is null then ef=e;d='"finance"';elsif ei is null then ei=e;d='"inventory"';elsif ep is null then ep=e;d='"procurement"';else es=e;d='"sales"';end if;
  perform public.work_business(jsonb_build_object('command','misc','action','file','id',e,'area',d#>>'{}','name','Synthetic evidence','path',auth.uid()::text||'/'||e||'.jpg','content_type','image/jpeg','size',10,'sha256',repeat('a',64)));
  insert into storage.objects(bucket_id,name) values('work-evidence',auth.uid()::text||'/'||e||'.jpg');
 end loop;
 c=public.work_business(jsonb_build_object('command','save','entity','customers','version',0,'data',jsonb_build_object('name','COMPLETION FIXTURE','email','fixture@example.invalid','legal_name','Fixture Legal Ltd','tags','education, AI','assigned_to',auth.uid())));cid=(c->>'id')::uuid;
 if c->>'legal_name'<>'Fixture Legal Ltd' or (c->>'version')::integer<>1 then raise exception 'Customer metadata/version failed';end if;
 c=public.work_business(jsonb_build_object('command','save','entity','enquiries','version',0,'data',jsonb_build_object('name','Enquiry fixture','subject','Test enquiry','message','Test requirements','priority','urgent','next_action','Call the procurement contact','evidence_id',es,'assigned_to',auth.uid())));
 if c->>'priority'<>'urgent' or (c->>'version')::integer<>1 then raise exception 'Enquiry priority/attachment/version failed';end if;
 cmd=jsonb_build_object('action','location','request_key',gen_random_uuid(),'data',jsonb_build_object('name','Completion warehouse'));
 c=public.work_operations(cmd);d=public.work_operations(cmd);if c<>d or (select count(*) from public.work_locations where name='Completion warehouse')<>1 then raise exception 'Operations idempotency failed';end if;
 denied=false;begin perform public.work_operations(jsonb_set(cmd,'{data,name}','"Different data"'));exception when raise_exception then denied=true;end;if not denied then raise exception 'Reused request key changed data';end if;
 c=public.work_business('{"command":"save","entity":"suppliers","version":0,"data":{"name":"COMPLETION SUPPLIER"}}');sid=(c->>'id')::uuid;
 c=public.work_business('{"command":"save","entity":"items","version":0,"data":{"sku":"COMPLETE-01","name":"Test equipment","kind":"stock","unit":"unit","unit_minor":100,"currency":"NGN"}}');item=(c->>'id')::uuid;
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',jsonb_build_object('kind','purchase','supplier_id',sid,'title','Completion purchase','document_date',current_date,'currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'description','Test equipment','quantity',20,'unit_minor',100)))));po=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','commercial_issue','id',po,'version',1,'reason','Synthetic owner approval'));
 select id into pol from public.work_commercial_lines where record_id=po;
 c=public.work_business(jsonb_build_object('command','stock','action','move','kind','receive','item_id',item,'location','Completion warehouse','quantity',10,'source_line_id',pol,'reason','Initial receiving fixture','request_key',gen_random_uuid()));stock=(c->>'id')::uuid;
 c=public.work_operations(jsonb_build_object('action','stock-hold','request_key',gen_random_uuid(),'data',jsonb_build_object('movement_id',stock,'quantity',4,'reason','Damaged packaging inspection','evidence_id',ei)));hold=(c->>'id')::uuid;
 c=public.work_operations(jsonb_build_object('action','inspection','request_key',gen_random_uuid(),'data',jsonb_build_object('purchase_id',po,'line_id',pol,'stage','receiving','result','rejected','quantity',5,'notes','Receiving inspection rejected fixture','evidence_id',ep)));
 perform public.work_business(jsonb_build_object('command','stock','action','move','kind','receive','item_id',item,'location','Completion warehouse','quantity',5,'source_line_id',pol,'reason','Rejected delivery fixture','request_key',gen_random_uuid()));
 if (select quarantined from public.work_stock_balances where item_id=item)<>9 then raise exception 'Rejected stock did not remain quarantined';end if;
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',jsonb_build_object('kind','order','customer_id',cid,'title','Completion sales order','document_date',current_date,'currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'description','Test equipment','quantity',10,'unit_minor',100)))));ord=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','commercial_issue','id',ord,'version',1,'reason','Synthetic owner approval'));
 select id into ol from public.work_commercial_lines where record_id=ord;
 denied=false;begin perform public.work_business(jsonb_build_object('command','stock','action','reserve','item_id',item,'location','Completion warehouse','quantity',7,'order_id',ord,'request_key',gen_random_uuid()));exception when raise_exception then denied=true;end;if not denied then raise exception 'Quarantine could be reserved';end if;
 perform public.work_operations(jsonb_build_object('action','release-hold','id',hold,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Inspection cleared and released')));
 perform public.work_operations(jsonb_build_object('action','cancel-quantity','request_key',gen_random_uuid(),'data',jsonb_build_object('line_id',ol,'quantity',2,'reason','Customer approved quantity reduction','evidence_id',es)));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',jsonb_build_object('kind','invoice','customer_id',cid,'source_id',ord,'title','Invalid overbilling fixture','document_date',current_date,'currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'source_line_id',ol,'description','Test equipment','quantity',9,'unit_minor',100)))));
 denied=false;begin perform public.work_business(jsonb_build_object('command','commercial_issue','id',c->>'id','version',1,'reason','Test cancelled quantity cap'));exception when raise_exception then denied=true;end;if not denied then raise exception 'Cancelled quantity could be invoiced';end if;
 c=public.work_business(jsonb_build_object('command','expense','action','save','request_key',gen_random_uuid(),'data',jsonb_build_object('supplier_id',sid,'title','Completion supplier bill','category','Shipping','cost_center','Hardware','purchase_id',po,'amount_minor',100,'currency','NGN','incurred_on',current_date,'evidence_id',ef)));expense=(c->>'id')::uuid;
 if (c->>'version')::integer<>1 then raise exception 'Expense classification changed initial version';end if;
 c=public.work_business(jsonb_build_object('command','expense','action','submit','id',expense,'version',1));
 c=public.work_business(jsonb_build_object('command','expense','action','approve','id',expense,'version',c->>'version','reason','Owner approval fixture'));
 c=public.work_business(jsonb_build_object('command','expense','action','pay','expense_id',expense,'amount_minor',100,'paid_on',current_date,'reference','Supplier payment fixture','evidence_id',ef,'request_key',gen_random_uuid()));pay=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','bank','action','import','rows',jsonb_build_array(jsonb_build_object('posted_on',current_date,'amount_minor',-100,'currency','NGN','reference','OUTGOING FIXTURE'))));select id into bank from public.work_bank_lines where reference='OUTGOING FIXTURE';
 perform public.work_operations(jsonb_build_object('action','match-outgoing','id',bank,'request_key',gen_random_uuid(),'data',jsonb_build_object('supplier_payment_id',pay)));
 denied=false;begin perform public.work_operations(jsonb_build_object('action','reverse-supplier-payment','id',pay,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Evidence-based correction','evidence_id',ef)));exception when raise_exception then denied=true;end;if not denied then raise exception 'Reconciled supplier payment reversed without unmatching';end if;
 perform public.work_operations(jsonb_build_object('action','unmatch-bank','id',bank,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Correct matching fixture')));
 perform public.work_operations(jsonb_build_object('action','reverse-supplier-payment','id',pay,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Evidence-based correction','evidence_id',ef)));
 c=public.work_reports_at(current_date);if not exists(select 1 from jsonb_array_elements(c->'payables') x where x->>'id'=expense::text and (x->>'outstanding_minor')::bigint=100) then raise exception 'Supplier reversal did not restore payable';end if;
 perform public.work_operations(jsonb_build_object('action','cost-allocation','request_key',gen_random_uuid(),'data',jsonb_build_object('expense_id',expense,'purchase_line_id',pol,'amount_minor',100,'basis','Agreed allocation to the purchase line')));
 denied=false;begin perform public.work_operations(jsonb_build_object('action','cost-allocation','request_key',gen_random_uuid(),'data',jsonb_build_object('expense_id',expense,'purchase_line_id',pol,'amount_minor',1,'basis','Excess allocation fixture')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Landed cost expense overallocated';end if;
 perform public.work_operations(jsonb_build_object('action','approval-rule','request_key',gen_random_uuid(),'data',jsonb_build_object('kind','purchase','currency','NGN','threshold_minor',1000,'approver_id',auth.uid(),'notes','Synthetic owner threshold')));
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',jsonb_build_object('kind','purchase','supplier_id',sid,'title','Above threshold fixture','document_date',current_date,'currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'description','Test equipment','quantity',20,'unit_minor',100)))));insert into completion_threshold_ids values((c->>'id')::uuid,'denied');
 c=public.work_business(jsonb_build_object('command','commercial_save','request_key',gen_random_uuid(),'version',0,'data',jsonb_build_object('kind','purchase','supplier_id',sid,'title','Below threshold fixture','document_date',current_date,'currency','NGN','lines',jsonb_build_array(jsonb_build_object('item_id',item,'description','Test equipment','quantity',1,'unit_minor',100)))));insert into completion_threshold_ids values((c->>'id')::uuid,'allowed');
 perform public.work_business(jsonb_build_object('command','misc','action','grant','email','editor-fixture@example.invalid','area','procurement','scope','all','write_access',true,'approve_access',true));
 c=public.work_operations(jsonb_build_object('action','supplier-bank','request_key',gen_random_uuid(),'data',jsonb_build_object('supplier_id',sid,'bank_name','Fixture bank','account_name','Fixture supplier','account_number','0000000000','currency','NGN','evidence_id',ef,'reason','Verified supplier payment details')));sid=(c->>'id')::uuid;
 denied=false;begin perform public.work_operations(jsonb_build_object('action','approve-bank','id',sid,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Owner approval reason')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Silent same-person bank approval allowed';end if;
 perform public.work_operations(jsonb_build_object('action','approve-bank','id',sid,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Explicit one-person owner exception','owner_exception',true)));
 e=gen_random_uuid();
 perform public.work_business(jsonb_build_object('command','misc','action','file','id',e,'area','support','name','Support acceptance fixture','path',auth.uid()::text||'/'||e||'.jpg','content_type','image/jpeg','size',10,'sha256',repeat('a',64)));
 insert into storage.objects(bucket_id,name) values('work-evidence',auth.uid()::text||'/'||e||'.jpg');
 c=public.work_business(jsonb_build_object('command','save','entity','cases','version',0,'data',jsonb_build_object('kind','maintenance','customer_id',cid,'title','Contract fixture','assigned_to',auth.uid())));contract=(c->>'id')::uuid;
 perform public.work_business(jsonb_build_object('command','delivery_work','action','service','case_id',contract,'version',0,'data',jsonb_build_object('agreed_response_minutes',120,'coverage','Synthetic contracted support')));
 perform public.work_operations(jsonb_build_object('action','pause-clock','id',contract,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Customer-approved service pause','evidence_id',e)));
 if not exists(select 1 from public.work_case_service where case_id=contract and clock_paused_at is not null and response_remaining_minutes>0) then raise exception 'Response clock did not retain remaining business minutes';end if;
 perform public.work_operations(jsonb_build_object('action','resume-clock','id',contract,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Customer-approved support resumption','evidence_id',e)));
 if exists(select 1 from public.work_case_service where case_id=contract and clock_paused_at is not null) then raise exception 'Response clock did not resume';end if;
 perform public.work_operations(jsonb_build_object('action','visit','request_key',gen_random_uuid(),'data',jsonb_build_object('case_id',contract,'scheduled_on',current_date,'status','completed','completed_on',current_date,'notes','Completed synthetic visit','evidence_id',e)));
 c=public.work_operations(jsonb_build_object('action','shipment','request_key',gen_random_uuid(),'data',jsonb_build_object('purchase_line_id',pol,'quantity',20,'status','shipped','shipped_on',current_date,'carrier','Fixture carrier')));
 denied=false;begin perform public.work_operations(jsonb_build_object('action','shipment','request_key',gen_random_uuid(),'data',jsonb_build_object('purchase_line_id',pol,'quantity',1,'status','planned')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Duplicate shipping quantity allowed';end if;
 perform public.work_business(jsonb_build_object('command','portal_admin','action','member','customer_id',cid,'email','completion-portal@example.invalid','active',true));
 perform public.work_business(jsonb_build_object('command','portal_admin','action','share','customer_id',cid,'record_id',ord,'active',true));select id into visit from public.work_portal_shares where record_id=ord;
 c=public.work_operations(jsonb_build_object('action','acceptance-request','request_key',gen_random_uuid(),'data',jsonb_build_object('customer_id',cid,'share_id',visit,'prompt','Please upload the synthetic customer acceptance record')));
 insert into completion_portal_ids values((c->>'id')::uuid,visit,cid);
 perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','request','email','completion-portal@example.invalid','token_hash',repeat('d',64),'cipher','synthetic-no-email-dispatched'));
 perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','exchange','token_hash',repeat('d',64),'session_hash',repeat('c',64)));
 c=public.work_operations(jsonb_build_object('action','queue-statement','request_key',gen_random_uuid(),'data',jsonb_build_object('customer_id',cid,'from','','to','','currency','NGN','recipient','fixture@example.invalid')));
 -- Keep the later paused-message assertion focused on its own message.
 perform public.work_operations(jsonb_build_object('action','pause-message','id',c->>'id','request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Statement snapshot review fixture')));
 c=public.work_business(jsonb_build_object('command','queue','customer_id',cid,'recipient','fixture@example.invalid','subject','Completion mail fixture','body','Synthetic test only','request_key',gen_random_uuid()));message=(c->>'id')::uuid;
 perform public.work_operations(jsonb_build_object('action','pause-message','id',message,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Review recipient before dispatch')));
 c=public.work_business_job(repeat('b',64),'{"action":"claim"}');if exists(select 1 from jsonb_array_elements(c) x where x->>'id'=message::text) then raise exception 'Paused message was leased';end if;
 perform public.work_operations(jsonb_build_object('action','resume-message','id',message,'request_key',gen_random_uuid(),'data',jsonb_build_object('reason','Recipient review completed')));
 c=public.work_business_job(repeat('b',64),'{"action":"claim"}');if not exists(select 1 from jsonb_array_elements(c) x where x->>'id'=message::text) then raise exception 'Reviewed message not leased';end if;
end;$$;
reset role;
select set_config('request.jwt.claims','{}',true);
select set_config('request.headers',jsonb_build_object('x-lutera-backup-proof',repeat('b',64))::text,true);
set local role anon;
do $$declare c jsonb;fid uuid=gen_random_uuid();req uuid;denied boolean;begin
 select request_id into req from completion_portal_ids;
 c=public.work_customer_portal(repeat('b',64),jsonb_build_object('action','state','session_hash',repeat('c',64)));
 if jsonb_array_length(c->'acceptance_requests')<>1 then raise exception 'Customer did not receive the explicitly shared evidence request';end if;
 denied=false;begin perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','reserve_evidence','session_hash',repeat('e',64),'request_id',req,'id',fid,'name','Synthetic evidence','content_type','application/pdf','size',10,'sha256',repeat('a',64)));exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Unknown portal session uploaded evidence';end if;
 c=public.work_customer_portal(repeat('b',64),jsonb_build_object('action','reserve_evidence','session_hash',repeat('c',64),'request_id',req,'id',fid,'name','Synthetic evidence','content_type','application/pdf','size',10,'sha256',repeat('a',64)));
 denied=false;begin perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','complete_evidence','session_hash',repeat('c',64),'request_id',req,'id',fid));exception when raise_exception then denied=true;end;if not denied then raise exception 'Missing storage bytes accepted';end if;
 insert into storage.objects(bucket_id,name) values('work-portal-evidence',c->>'path');
 perform public.work_customer_portal(repeat('b',64),jsonb_build_object('action','complete_evidence','session_hash',repeat('c',64),'request_id',req,'id',fid));
 c=public.work_customer_portal(repeat('b',64),jsonb_build_object('action','state','session_hash',repeat('c',64)));
 if c#>>'{acceptance_requests,0,status}'<>'completed' then raise exception 'Customer evidence completion not retained';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal2','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$declare denied boolean;r record;begin
 for r in select * from completion_threshold_ids loop
  denied=false;begin perform public.work_business(jsonb_build_object('command','commercial_issue','id',r.id,'version',1,'reason','Independent procurement approval fixture'));exception when insufficient_privilege then denied=true;end;
  if (r.expected='denied')<>denied then raise exception 'Approval threshold did not enforce named approver';end if;
 end loop;
 denied=false;begin perform public.work_operations(jsonb_build_object('action','location','request_key',gen_random_uuid(),'data',jsonb_build_object('name','Unauthorized location')));exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Editor gained inventory mutation access';end if;
 if exists(select 1 from public.work_supplier_bank) then raise exception 'Editor read supplier bank details';end if;
end;$$;
reset role;
set local role anon;
do $$declare denied boolean;begin
 denied=false;begin perform public.work_operations('{}');exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Anonymous operations RPC access';end if;
end;$$;
reset role;
rollback;
select 'PASS: completion controls enforce quarantine, cancellation caps, reversal/reconciliation, cost caps, bank approval, outbox pause, role denial and idempotency.' result;
